<?php
$cycle=selectedCycle();if(!$cycle){emptyState('Crea un ciclo escolar para comenzar.');return;}
$term=max(1,min((int)$cycle['periodos'],(int)($_GET['bimestre']??1)));$group=max(0,(int)($_GET['grupo']??0));$page=max(1,(int)($_GET['pagina']??1));$fields=cycleFields((int)$cycle['id_ciclo']);
$total=(int)students($u,(int)$cycle['id_ciclo'],true,null,0,'',$group,true)[0]['total'];$list=students($u,(int)$cycle['id_ciclo'],true,40,($page-1)*40,'',$group);$grades=gradeMap(gradeRows($list,(int)$cycle['id_ciclo'],$term));
?>
<section class="card glass"><form class="filters" method="get"><input type="hidden" name="vista" value="calificaciones"><label>Ciclo<select name="ciclo" data-filter><?php foreach(cycles() as $c): ?><option value="<?=e($c['id_ciclo'])?>" <?=(int)$c['id_ciclo']===(int)$cycle['id_ciclo']?'selected':''?>><?=e($c['nombre'])?></option><?php endforeach; ?></select></label><label>Periodo<select name="bimestre" data-filter><?php for($i=1;$i<=(int)$cycle['periodos'];$i++): ?><option value="<?=$i?>" <?=$i===$term?'selected':''?>><?=e($cycle['tipo_periodo'])?> <?=$i?></option><?php endfor; ?></select></label><?php if(!$isTutor): ?><label>Grupo<select name="grupo" data-filter><option value="">Todos mis grupos</option><?php foreach(teacherGroups($u,(int)$cycle['id_ciclo']) as $g): ?><option value="<?=e($g['ID_Grupo'])?>" <?=(int)$g['ID_Grupo']===$group?'selected':''?>><?=e($g['Grado'].'° '.$g['Grupo'])?></option><?php endforeach; ?></select></label><?php endif; ?></form>
<div class="toolbar"><p class="help">Promedio ponderado por campo, redondeado a un decimal al final. Los pendientes no cuentan como cero.</p><div class="buttons"><a class="button small" href="<?=e(url('process/export.php?tipo=xlsx&ciclo='.$cycle['id_ciclo'].'&bimestre='.$term.'&grupo='.$group))?>">Excel</a><a class="button small" href="<?=e(url('process/export.php?tipo=pdf&ciclo='.$cycle['id_ciclo'].'&bimestre='.$term.'&grupo='.$group))?>">PDF</a></div></div>
<?php if($cycle['estado']!=='ACTIVO'): ?><div class="notice">Ciclo <?=e(mb_strtolower($cycle['estado']))?>: consulta del historial.</div><?php endif; ?>
<?php if(!$list): emptyState('No hay alumnos inscritos con estos filtros.'); else: ?>
<form id="grade-grid" action="<?=e(url('process/action.php'))?>" method="post" data-draft-key="<?=e($u['ID_Usuario'].'-'.$cycle['id_ciclo'].'-'.$term.'-'.$group.'-'.$page)?>"><?=csrf()?><input type="hidden" name="ciclo" value="<?=e($cycle['id_ciclo'])?>"><input type="hidden" name="bimestre" value="<?=$term?>">
<div class="table-wrap" tabindex="0" role="region" aria-label="Captura de calificaciones"><table class="grade-table"><thead><tr><th>Alumno</th><?php foreach($fields as $f): ?><th><?=e($f['Nombre_Campo'])?><small>Ponderación: <?=e($f['peso'])?>%</small></th><?php endforeach; ?><th>Promedio</th></tr></thead><tbody>
<?php foreach($list as $a):$avg=gradeAverage($grades[$a['ID_Alumno']]??[],$fields); ?><tr><td><a href="<?=e(viewUrl('expediente').'&ciclo='.$cycle['id_ciclo'].'&alumno='.$a['ID_Alumno'])?>"><?=e($a['nombre_completo'])?></a><small><?=e($a['grupo'])?><?=$a['activo']?'':' · Baja'?></small></td><?php foreach($fields as $f):$note=$grades[$a['ID_Alumno']][$f['ID_Campo']]??null;$can=$cycle['estado']==='ACTIVO'&&$a['activo']&&$a['verificado']&&mayGrade($u,(int)$cycle['id_ciclo'],(int)$a['grupo_ciclo'],(int)$f['ID_Campo']); ?><td><?php if($can): ?><input class="grade-cell" type="text" inputmode="decimal" maxlength="4" aria-label="<?=e($a['nombre_completo'].' · '.$f['Nombre_Campo'])?>" data-student="<?=e($a['ID_Alumno'])?>" data-field="<?=e($f['ID_Campo'])?>" data-revision="<?=e($note['revision']??0)?>" data-original="<?=e($note['Calificacion_Numerica']??'')?>" value="<?=e($note['Calificacion_Numerica']??'')?>" placeholder="—"><?php else: ?><?=e($note['Calificacion_Numerica']??'—')?><?php endif; ?></td><?php endforeach; ?><td><?=e($avg['value']===null?'—':number_format($avg['value'],1))?><small><?=$avg['complete']?'Completo':'Parcial '.$avg['count'].'/'.count($fields)?></small></td></tr><?php endforeach; ?></tbody></table></div>
<?php if(!$isTutor&&$cycle['estado']==='ACTIVO'): ?><div class="capture-bar"><span id="grade-status" role="status">Sin cambios pendientes.</span><div class="buttons"><button class="button" type="button" id="draft-restore">Recuperar borrador</button><button class="button" type="button" id="draft-discard">Descartar cambios</button><button class="button primary" type="submit">Guardar cambios del grupo</button></div></div><p class="help">Usa Tab o Enter. Puedes pegar un bloque de celdas de Excel: se muestra aquí antes de guardarlo. Vaciar una celda conserva la nota registrada. El borrador se conserva en esta pestaña; no se envía hasta pulsar Guardar.</p><?php endif; ?></form>
<?php endif; ?>
<div class="buttons"><?php if($page>1): ?><a class="button small" href="<?=e(viewUrl('calificaciones').'&ciclo='.$cycle['id_ciclo'].'&bimestre='.$term.'&grupo='.$group.'&pagina='.($page-1))?>">Anterior</a><?php endif; ?><span class="help">Página <?=$page?> · <?=$total?> alumnos</span><?php if($page*40<$total): ?><a class="button small" href="<?=e(viewUrl('calificaciones').'&ciclo='.$cycle['id_ciclo'].'&bimestre='.$term.'&grupo='.$group.'&pagina='.($page+1))?>">Siguiente</a><?php endif; ?></div></section>
